package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.FMLInitializationEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.capacitor.*;import dev.industrialtechnology.integration.FactoryComputerDriver;
import li.cil.oc.api.*;import li.cil.oc.api.machine.Machine;import li.cil.oc.api.network.*;
import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.tileentity.TileEntity;import net.minecraft.item.*;import net.minecraft.init.Blocks;import net.minecraft.inventory.IInventory;import net.minecraft.item.crafting.*;import net.minecraft.nbt.*;import net.minecraftforge.common.util.*;
@Mod(modid="industrialtech_oc_checks",name="Disposable full OpenComputers checks",version="1",dependencies="required-after:industrialtech;required-after:OpenComputers")
public final class OpenComputersServerChecks {
    private final List<String> report=new ArrayList<String>();private int ticks,failed;private boolean done,setup;private WorldServer w;private FakePlayer player;private TileEntity computer;private Machine machine;private boolean adapter;private String stage="initial";
    interface Check{void run()throws Exception;}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    void test(String label,Check check){try{check.run();report.add("PASS: "+label);}catch(Throwable t){failed++;report.add("FAIL: "+label+" :: "+t);IndustrialTechnology.log.error(label,t);}}
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.ocTest"))FMLCommonHandler.instance().bus().register(this);}
    static Object invoke(Object object,String name,Object... args)throws Exception{for(Method m:object.getClass().getMethods())if(m.getName().equals(name)&&m.getParameterTypes().length==args.length){m.setAccessible(true);return m.invoke(object,args);}throw new NoSuchMethodException(name);}
    private ItemStack stack(String name){li.cil.oc.api.detail.ItemInfo info=li.cil.oc.api.Items.get(name);check(info!=null,"Missing OC item: "+name);return info.createItemStack(1);}
    private TileEntity place(String name,int x,int y,int z){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,y-1,z,Blocks.stone,0,3);ItemStack item=stack(name);player.setPosition(x+.5,y,z+2);player.inventory.mainInventory[0]=item;if(!item.tryPlaceItemIntoWorld(player,w,x,y-1,z,1,.5F,1,.5F))throw new AssertionError("Cannot place "+name);return w.getTileEntity(x,y,z);}
    private void insert(ItemStack stack){IInventory inv=(IInventory)computer;for(int i=0;i<inv.getSizeInventory();i++)if(inv.getStackInSlot(i)==null&&inv.isItemValidForSlot(i,stack)){inv.setInventorySlotContents(i,stack);return;}throw new AssertionError("No slot for "+stack);}
    private void prepare()throws Exception{
        w=MinecraftServer.getServer().worldServerForDimension(0);player=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("2fdc4832-9388-4d47-b635-11811028e290"),"OCIntegration")){@Override public void sendPlayerAbilities(){}@Override public void addChatMessage(net.minecraft.util.IChatComponent c){}};player.theItemInWorldManager.setGameType(WorldSettings.GameType.CREATIVE);
        if(new File("oc-world-saved.done").exists()){stage="restart";w.getChunkFromChunkCoords(20>>4,24>>4);computer=w.getTileEntity(20,70,24);check(computer!=null,"saved computer missing");machine=(Machine)invoke(computer,"machine");setup=true;return;}
        test("Complete original content registers its native blocks, hardware and robotics",()->{for(String name:new String[]{"case1","case2","case3","caseCreative","screen1","screen2","screen3","keyboard","adapter","cable","assembler","charger","disassembler","diskDrive","hologram1","hologram2","printer","transposer","rack","cpu1","cpu2","cpu3","ram1","ram6","hdd1","hdd3","eeprom","robot","drone","tablet","microcontroller","internetCard","redstoneCard1","wlanCard1","wlanCard2"})stack(name);});
        test("Original OpenOS, Lua firmware, native libraries and default recipe resources are accessible",()->{for(String resource:new String[]{"assets/opencomputers/lua/bios.lua","assets/opencomputers/lua/machine.lua","assets/opencomputers/loot/openos/init.lua","application.conf","META-INF/oc_at.cfg"})check(getClass().getClassLoader().getResource(resource)!=null,"Missing "+resource);li.cil.oc.api.fs.FileSystem fs=li.cil.oc.api.FileSystem.fromClass(Class.forName("li.cil.oc.OpenComputers"),"opencomputers","loot/openos");check(fs!=null&&fs.exists("init.lua")&&fs.exists("lib/filesystem.lua"),"OpenOS filesystem incomplete");fs.close();});
        test("Original survival crafting recipes are loaded",()->{int recipes=0;for(Object o:CraftingManager.getInstance().getRecipeList()){ItemStack out=((IRecipe)o).getRecipeOutput();if(out!=null&&li.cil.oc.api.Items.get(out)!=null)recipes++;}check(recipes>80,"Only "+recipes+" OC recipes");report.add("INFO: OC crafting recipes="+recipes);});
        test("All original item descriptors are recorded for comparison with stock OC",()->{Object descriptors=Class.forName("li.cil.oc.common.init.Items").getMethod("descriptors").invoke(null);Object iterator=invoke(descriptors,"keysIterator");List<String> names=new ArrayList<String>();while((Boolean)invoke(iterator,"hasNext"))names.add(String.valueOf(invoke(iterator,"next")));Collections.sort(names);Files.write(Paths.get("oc-catalog.txt"),names,StandardCharsets.UTF_8);check(names.size()>100,"Incomplete OC catalog: "+names.size());report.add("INFO: OC descriptors="+names.size());});
        test("A real creative computer accepts CPU, RAM and an EEPROM",()->{computer=place("caseCreative",20,70,24);insert(stack("cpu3"));insert(stack("ram6"));insert(stack("ram6"));byte[] code=("local a=computer.tmpAddress() local h=component.invoke(a,'open','/oc-integration-ok','w') component.invoke(a,'write',h,'original-lua-runtime-ok') component.invoke(a,'close',h) while true do computer.pullSignal(1) end").getBytes(StandardCharsets.UTF_8);insert(li.cil.oc.api.Items.registerEEPROM("OC integration probe",code,new byte[0],false));machine=(Machine)invoke(computer,"machine");check(machine!=null,"no machine");});
        if(Loader.instance().getIndexedModList().get("industrialtech").getVersion().equals("2.9.0"))test("Our full RF capacitor network is read through the actual OC adapter driver",()->{for(int x=22;x<25;x++)w.setBlock(x,70,24,ModRegistry.capacitorBank,0,3);li.cil.oc.api.driver.SidedBlock driver=li.cil.oc.api.Driver.driverFor(w,22,70,24,ForgeDirection.WEST);check(driver!=null&&driver.worksWith(w,22,70,24,ForgeDirection.WEST),"driver missing");place("adapter",21,70,24);adapter=true;});
        if(Loader.isModLoaded("hbm"))test("Combined core loader preserves the existing HBM battery observation transformer",()->{check(dev.industrialtechnology.energy.MeteredBattery.class.isAssignableFrom(Class.forName("com.hbm.tileentity.machine.storage.TileEntityMachineBattery")),"HBM meter hook missing");});
        setup=computer!=null&&machine!=null;
    }
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||!MinecraftServer.getServer().isDedicatedServer()||++ticks<10)return;
        try{
            if(ticks==10){prepare();if(!setup){finish();return;}}
            if(ticks==20){test("The original computer starts its real Lua machine",()->{((Connector)machine.node()).changeBuffer(1000000);check(machine.start()||machine.isRunning(),"Cannot start: "+machine.lastError());});}
            if(ticks==120){if(adapter)test("OC invokes the original Adapter component and reads one full RF network",()->{String address=null;for(Map.Entry<String,String> component:machine.components().entrySet())if(component.getValue().equals("industrialtech"))address=component.getKey();check(address!=null,"No industrialtech component in "+machine.components());scala.collection.Map values=(scala.collection.Map)machine.invoke(address,"getEnergy",new Object[0])[0];check(Boolean.TRUE.equals(values.apply("available"))&&"RF".equals(values.apply("unit"))&&((Number)values.apply("capacity")).longValue()==75000000L&&((Number)values.apply("batteries")).intValue()==3,"RF data "+values);check(((TileCapacitorBank)w.getTileEntity(23,70,24)).snapshot().getLong("Stored")==0,"adapter moved energy");});test("Original native Lua VM executes EEPROM firmware and writes a real filesystem",()->{check(machine.isRunning(),"Machine stopped: "+machine.lastError());Object[] result=machine.invoke(machine.tmpAddress(),"exists",new Object[]{"/oc-integration-ok"});check(result.length>0&&Boolean.TRUE.equals(result[0]),"Lua did not create its marker");check(machine.architecture().getClass().getName().contains(".luac."),"Native VM not active: "+machine.architecture().getClass());report.add("INFO: VM="+machine.architecture().getClass().getName());});
                if(stage.equals("initial")){test("Full original computer hardware and machine state save for a real restart",()->{w.saveAllChunks(true,null);w.mapStorage.saveAllData();Files.write(Paths.get("oc-world-saved.done"),Arrays.asList("saved"),StandardCharsets.UTF_8);});}
                else test("Computer hardware survives a genuine server restart",()->{IInventory inventory=(IInventory)computer;int installed=0;for(int i=0;i<inventory.getSizeInventory();i++)if(inventory.getStackInSlot(i)!=null)installed++;check(installed==4,"hardware lost: "+installed);});
                finish();}
        }catch(Throwable t){failed++;report.add("FAIL: setup/tick :: "+t);IndustrialTechnology.log.error("OpenComputers checks",t);finish();}
    }
    private void finish(){if(done)return;done=true;try{report.add("Failed: "+failed);Files.write(Paths.get("oc-"+stage+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}
}
